/* ══════════════════ PART 3 · MCQ + notes (typed) ══════════════════ */
function buildSection3() {
  const feats=[
    ['A','can stay in one place underwater'],
    ['B','has a special shape'],
    ['C','is made from special strong material'],
    ['D','moves well over rough terrain'],
    ['E','operates best in very deep water'],
    ['F','senses dangers under the seabed'],
    ['G','uses solar energy']
  ];
  const vehicles=[[21,'S83'],[22,'Sea Explorer'],[23,'Wave Rider'],[24,'T602']];
  const pool=feats.map(([l,t],i)=>'<div class="drag-chip eh-opt" id="dchip-av-'+i+'" data-val="'+l+'" data-pool="pool-av">'+
    '<span class="eh-opt-l">'+l+'</span><span class="eh-opt-t">'+t+'</span></div>').join('');
  const mcqs=[
    [25,"The students agree that a scientist&rsquo;s choice of underwater vehicle depends on",[{letter:'A',text:'the water conditions.'},{letter:'B',text:'the project&rsquo;s budget.'},{letter:'C',text:'the data required.'}]],
    [26,"Where did scientists think the oil off the Californian coast had come from?",[{letter:'A',text:'a tanker'},{letter:'B',text:'vehicles on land'},{letter:'C',text:'fishing boats'}]],
    [27,"Why was the underwater vehicle known as &lsquo;Alvin&rsquo; chosen to investigate the oil?",[{letter:'A',text:'It was the most advanced vehicle at the time.'},{letter:'B',text:'It was able to take photos of the seabed.'},{letter:'C',text:'It was designed specifically for coastal sea conditions.'}]],
    [28,"Scientists were able to use Alvin&rsquo;s samples to analyse",[{letter:'A',text:'how long oil would stay in the seabed.'},{letter:'B',text:'how much oil there was in the seabed.'},{letter:'C',text:'the chemicals in the oil found in the seabed.'}]],
    [29,"Assessing the effect of oil on sea animals is difficult because",[{letter:'A',text:'oil can be complex and unpredictable.'},{letter:'B',text:'we still can&rsquo;t access certain underwater areas.'},{letter:'C',text:'there are so many different species of sea animal.'}]],
    [30,"Scientists like studying natural oil seeps because these seeps",[{letter:'A',text:'show us how animals change to suit their environment.'},{letter:'B',text:'tend to be concentrated in one specific area.'},{letter:'C',text:'don&rsquo;t require as much equipment or special clothing.'}]]
  ];

  return `<div class="section-block" id="listening-part-3">
    <div class="section-head">
      <div class="num">Questions 21&ndash;24</div>
      <h2>Autonomous underwater vehicles</h2>
      <div class="instruction">What special feature will each of the following autonomous underwater vehicles (AUVs) have? Move the correct answer into the gap next to questions 21&ndash;24.</div>
    </div>
    <div class="opt-box drag-pool" id="pool-av" data-pool="pool-av">${pool}</div>
    ${kbHelp()}
    <div class="drag-match-layout">
      <div class="drag-left">
        <div class="drag-col-hdr">Vehicle</div>
        <div class="drag-items wide-drops">${matchRows(vehicles)}</div>
      </div>
    </div>
    <div class="section-head" style="margin-top:24px">
      <div class="num">Questions 25&ndash;30</div>
      <div class="instruction">Choose the correct letter, <em>A, B or C</em>.</div>
    </div>
    ${mcqs.map(([id,q,o])=>mcqCard(id,q,o)).join('')}
  </div>`;
}


/* ══════════════════ PART 4 · notes (typed) ══════════════════ */
function buildSection4() {
  return `<div class="section-block" id="listening-part-4">
    <div class="section-head">
      <div class="num">Questions 31&ndash;40</div>
      <div class="instruction">Complete the notes below. Write <em>ONE WORD ONLY</em> for each answer.</div>
      <h2>Life on the International Space Station</h2>
    </div>
    <div class="note-flow"><div class="subhead">Background</div>-${nb(1)}Station was occupied by international teams of scientists over several months.<br>
      <br>-${nb(1)}Research was done on living conditions.
      <div class="subhead"><br>Early impressions</div>-${nb(1)}The air smelt ${gapInput(31)}<br>
      <br>-${nb(1)}The temperature was easy to adjust.<br>
      <br>-${nb(1)}The food had enough ${gapInput(32)}<br>
      <br>-${nb(1)}${gapInput(33)} was efficient
      <div class="subhead"><br>Problems</div>-${nb(1)}Difficulties with air filters caused lack of ${gapInput(34)}<br>
      <br>-${nb(1)}It was difficult to keep cabin objects secure.<br>
      <br>-${nb(1)}Systems were incompatible &ndash; e.g. there were problems when mixing ${gapInput(35)} because of the preservatives<br>
      <br>-${nb(1)}The ${gapInput(36)} available were not always suitable for their purpose<br>
      <br>-${nb(1)}It was difficult to access the ${gapInput(37)} for equipment maintenance
      <div class="subhead"><br>Suggested improvements</div>-${nb(1)}Systems and equipment should undergo more extensive ${gapInput(38)}<br>
      <br>-${nb(1)}In language training, astronauts needed practice in understanding the controller&rsquo;s ${gapInput(39)}<br>
      <br>-${nb(1)}There should be less emphasis on ${gapInput(40)} and more on other issues.</div>
  </div>`;
}


